from pathlib import Path
import ast
import json
import re

prefix = 'round-alignment-polynomial-arrays'
previous = 'round-alignment-residue-exposure'
modules = ['Hindman168/' + n + '.lean' for n in [
    'AlignmentPolynomialInputShifts', 'AlignmentPolynomialArrayGroup',
    'AlignmentArrayInputTranslations', 'AlignmentPolynomialArrayLattice',
    'AlignmentPolynomialModelArrays', 'AlignmentJointArrayNilpotence']]
ds = {p: re.findall(r'^\s*(?:noncomputable\s+)?(theorem|def)\s+(\w+)',
    Path(p).read_text(encoding='utf-8'), re.M) for p in modules}
assert sum(k == 'theorem' for v in ds.values() for k, _ in v) == 25
assert sum(k == 'def' for v in ds.values() for k, _ in v) == 13
assert sum(map(len, ds.values())) == 38
baseline = json.loads(Path(prefix + '-baseline.json').read_text(encoding='utf-8'))
assert baseline == json.loads(Path('verification-manifest.json').read_text(encoding='utf-8'))
assert len(baseline['files']) == 1333
components = [
    'Integer polynomial input translation is the literal substitution X_j -> X_j+v_j. Evaluation agrees with input addition and total degree does not increase. The degree bound is proved from the actual monomial expansion, and actual affine array exponents have total degree at most one.',
    'A concrete integer-input polynomial array subgroup is generated by power arrays with total degree at most j+1 and values in native group lower-central level j. Constant arrays and the original affine-power-times-base model arrays belong to it. Evaluation homomorphisms prove termination of its lower central series at the original model step and the resulting nilpotency-class bound.',
    'Input translations restrict to actual group automorphisms of that concrete polynomial array subgroup. Translation preserves its generators by polynomial substitution and preserves the group by genuine closure induction; inverse translations and exact evaluation compatibility are proved.',
    'The genuine pointwise original lattice defines a subgroup of the array group, and input translations preserve it. Evaluation and input translation descend to the actual nonnormal lattice coset spaces. Their compatibility is exact; evaluation is continuous in the inherited pointwise topology. No lattice normality, discreteness, compactness or finite-dimensional manifold is assumed.',
    'The actual affine model array g^(k+sum u_j Delta_j)*x is an element of the concrete array group. Its translated input has exactly the new intercept. The pivot array orbit with intercept k+t*ell is exactly a linear left orbit under the constant array g^t, for every signed integer ell.',
    'The joint product of all model array groups has lower central series terminating at the same common model step and has nilpotency class at most that step. This proof permits heterogeneous original model groups and coordinate sets; it does not infer nilpotency of an unconstructed group containing the input-shift automorphisms.'
]
remaining = baseline['last_round']['remaining'].replace(
    'The actual earlier-variable exposure fixes every residue and slot shift, full own-target numerators and array residues; exact affine tail dependence of each progression and the whole own-target progression sum is proved.',
    'The actual earlier-variable exposure fixes every residue and slot shift, full own-target numerators and array residues; exact affine tail dependence of each progression and the whole own-target progression sum is proved. Concrete integer-input polynomial array groups, their common nilpotence bound, input translations, pointwise lattice coset evaluation and exact affine model linear orbits are constructed. Identification with the paper finite-dimensional native Lie array group, coefficient bounds and topology, discrete cocompact lattice and smooth evaluation remain unproved.')
assert remaining != baseline['last_round']['remaining']
reviews = [
    'PROGRESS. The preceding residue-exposure round was rechecked successfully and its authoritative 1333-source manifest was copied before new proof edits. Retained proof sources and exact selected axiom sets remain fixed.',
    'Input translation is an actual multivariable integer polynomial substitution. The degree estimate uses each monomial in the original support, degree bounds for products and powers, and the actual monomial degree bound. Cancellation in an arbitrary polynomial sum is not incorrectly handled by an induction that assumes the original degree equals a sum of degrees.',
    'The concrete subgroup consists of integer-input functions generated by controlled-degree polynomial powers. Mathlib lower-central level zero is the whole original group; degree j+1 therefore corresponds to the paper positive-degree lower-central level. Membership of constants and the actual original affine model arrays is proved. Identification with the full paper Lie polynomial-array group is not asserted.',
    'Nilpotence is proved by actual evaluation homomorphisms: a member of the array lower-central series evaluates into the original model lower-central series at every input. Pointwise equality then forces it to be one. The same argument and a bounded-product lower-central bound cover all jointly stored model factors. Neither commutativity nor finiteness of the integer input space is assumed.',
    'The array input translations are genuine multiplicative equivalences. A shifted generator has the same original group element and a translated polynomial of no larger degree. Closure induction covers products and inverses. This does not prove that the group generated by array values and input automorphisms has the same nilpotence class; the later face-lift and shear construction is still required.',
    'The lattice subgroup uses precisely the requirement that every integer-input evaluation belongs to the original lattice. The original lattice may be nonnormal. Coset evaluation and translation are constructed by quotient lifts with explicit representative compatibility, and their evaluation relation is proved on every coset.',
    'Continuity of coset evaluation refers to the inherited pointwise function topology. No finite-dimensional manifold, lattice discreteness or cocompactness follows from this construction alone. Those claims require identification with the native Lie coefficient array group, bounded coefficient geometry and a genuine lattice argument.',
    'The stored affine model arrays retain their original g, x, signed integer intercept and actual signed progression coefficients. Input shifts change the intercept by the precise dot product. Changing the pivot progression index yields exactly the constant-array left orbit, including negative indices. No convenient substitute observable or commuting original model group is introduced.',
    'Six modules contain 25 theorems and 13 definitions; all 38 declarations are selected for kernel audit. No proof holes, new axioms, structures, global instances, unsafe code or resource settings are introduced. Strict focused checks, full build, kernel checking, exact retained-source and axiom comparisons and final recheck must terminate successfully.',
    remaining
]
source = Path(previous + '-audit.py').read_text(encoding='utf-8')
replacements = {
    "len(baseline['files']) == 1329": "len(baseline['files']) == 1333",
    "'baseline_hash_count': 1329": "'baseline_hash_count': 1333",
    'len(set(names)) == 23': 'len(set(names)) == 38',
    "for values in ds.values() for kind, _ in values) == 18": "for values in ds.values() for kind, _ in values) == 25",
    "for values in ds.values() for kind, _ in values) == 5": "for values in ds.values() for kind, _ in values) == 13",
    "'theorem_count': 18, 'selected_report_count': 23": "'theorem_count': 25, 'selected_report_count': 38",
    "names == registration['names'] and len(names) == 23": "names == registration['names'] and len(names) == 38",
    'len(own) == 1315': 'len(own) == 1321',
    'len(actual) == 5967': 'len(actual) == 6005',
    "len({f['path'] for f in files}) == 1333": "len({f['path'] for f in files}) == 1339",
    'new_theorems=18, new_definitions=5, new_structures=0, new_instances=0, new_axiom_reports=23':
        'new_theorems=25, new_definitions=13, new_structures=0, new_instances=0, new_axiom_reports=38',
    'hindman_module_count=1315': 'hindman_module_count=1321',
    'selected_axiom_report_count=5967, source_scan_module_count=1324':
        'selected_axiom_report_count=6005, source_scan_module_count=1330',
    'new_module_count=4, new_theorem_count=18': 'new_module_count=6, new_theorem_count=25',
    'new_selected_report_count=23': 'new_selected_report_count=38',
    "reference_scope='08_alignment conditional face invariance: exposed residue data and exact affine progression dependence'":
        "reference_scope='08_alignment integer polynomial array groups, input shifts, lattice coset evaluation and model linear orbits'"
}
for old in replacements:
    assert old in source, old
pattern = re.compile('|'.join(re.escape(s) for s in sorted(replacements, key=len, reverse=True)))
source = pattern.sub(lambda m: replacements[m.group()], source)
values = {'PREFIX': prefix, 'OLD': previous, 'MODULES': modules,
    'COMPONENTS': components, 'REMAINING': remaining, 'EXPECTED_NEW_AXIOM_FREE': set()}
lines = source.splitlines(keepends=True)
edits = []
for node in ast.parse(source).body:
    if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
        name = node.targets[0].id
        if name in values:
            edits.append((node.lineno-1, node.end_lineno, name + ' = ' + repr(values[name]) + '\n'))
assert len(edits) == len(values)
for start, end, replacement in reversed(edits):
    lines[start:end] = [replacement]
source = ''.join(lines)
for node in ast.walk(ast.parse(source)):
    if isinstance(node, ast.keyword) and node.arg == 'application_review':
        original = ast.get_source_segment(source, node.value)
        assert source.count(original) == 1
        source = source.replace(original, repr(reviews), 1)
        break
else:
    raise AssertionError('review field missing')
anchor = "    prior = read('Hindman168/PrincipalPredictionModels.lean')\n"
scope = '''    array = read('Hindman168/AlignmentPolynomialArrayGroup.lean')
    assert 'Subgroup.closure (alignmentPolynomialArrayGenerators σ G)' in array
    assert 'p.totalDegree ≤ j + 1' in array
    assert 'alignmentPolynomialArrayGroup_lowerCentral_bot' in array
    assert 'hG : (⊤ : Subgroup G).lowerCentralSeries s = ⊥' in array
    lattice = read('Hindman168/AlignmentPolynomialArrayLattice.lean')
    assert 'Subgroup.pi Set.univ' in lattice
    assert 'Quotient.lift' in lattice
    assert 'alignmentPolynomialArrayCosetTranslation_evaluation' in lattice
    assert 'CompactSpace' not in lattice and '.Normal' not in lattice
    model = read('Hindman168/AlignmentPolynomialModelArrays.lean')
    assert 'alignmentPolynomialModelOrbit_linear' in model
    assert 'alignmentConstantArray (g ^ t) ^ ℓ' in model
'''
assert source.count(anchor) == 1
source = source.replace(anchor, scope + anchor, 1)
ast.parse(source)
Path(prefix + '-audit.py').write_text(source, encoding='utf-8')
focused = Path('check-alignment-residue-exposure.py').read_text(encoding='utf-8')
assert focused.count("prefix = 'round-alignment-residue-exposure'") == 1
focused = focused.replace("prefix = 'round-alignment-residue-exposure'", 'prefix = ' + repr(prefix))
Path('check-alignment-polynomial-arrays.py').write_text(focused, encoding='utf-8')
print(json.dumps({'prepared_modules': len(modules), 'theorems': 25, 'definitions': 13, 'declarations': 38}))
